function plValidateImport(v){const c=v.character;if(v.version!==1||!c||!plClass(c)||!plSub(c)||!Array.isArray(c.traits)||c.traits.length!==6||!c.traits.every(Number.isFinite)||!Number.isInteger(c.level)||c.level<1||c.level>10||!Array.isArray(c.cards)||c.cards.some(x=>!plCard(x.i)||plCard(x.i).c!=='d')||new Set(c.cards.map(x=>x.i)).size!==c.cards.length||!Array.isArray(c.experiences)||!Array.isArray(c.subcards))throw Error('Il file non è un backup personaggio valido.');if(plCard(c.ancestry)?.c!=='a'||plCard(c.community)?.c!=='c'||c.subcards.some(i=>plCard(i)?.c!=='s')||c.experiences.some(x=>typeof x.name!=='string'||!Number.isFinite(x.value))||typeof c.name!=='string'||!Number.isFinite(c.proficiency))throw Error('Campi del backup non validi.');if(c.multiclass){const k=PLAYER_RULES.classes[c.multiclass.className];if(!k||!k.domains.includes(c.multiclass.domain)||!k.subclasses.some(x=>x.name===c.multiclass.subclass))throw Error('Multiclass non valido.');}if(c.items!==undefined&&(!Array.isArray(c.items)||c.items.some(x=>!eqItem(x.gear)||typeof x.uid!=='string'||!Number.isInteger(x.qty)||x.qty<1||x.qty>99||eqItem(x.gear).kind==='consumable'&&x.qty>5)))throw Error('Inventario del backup non valido.');const clean=plNew(),allowed=new Set([...Object.keys(clean),'multiclass','companionData','conditions','spellTrait','classResourceNotes','gmAt','items','equipmentState','equipmentMigrated','inventoryWeaponSlots','inventoryCardsMigrated','outgoingTrades','receivedTrades',...Array.from({length:2},(_,i)=>['Name','Trait','Damage','Feature','Type'].map(x=>'inventoryWeapon'+i+x)).flat()]);for(const [key,value]of Object.entries(plClone(c)))if(allowed.has(key))clean[key]=value;clean.id=plId();clean.campaigns=[];clean.updated=Date.now();plClampTracks(clean);if(plActive(clean).length>eqLoadoutMax(clean))throw Error('Il backup supera le 5 carte attive.');return clean}
