/* Level up: la card scelta vola fino alla lista dei miglioramenti assegnati, così si vede dove è finita. */
addEventListener('click',e=>{const b=e.target.closest?.('[data-pl="adv"],[data-pl="adv-confirm"]');if(!b||b.disabled||!PL.level)return;const src=b.closest('.pl-adv-open')||b,from=src.getBoundingClientRect(),label=src.querySelector('b')?.textContent||'',before=PL.level.choices.length,pending=b.dataset.pl==='adv'&&['traits','experiences','subclass','multiclass'].includes(b.dataset.key);if(pending)return;
 requestAnimationFrame(()=>requestAnimationFrame(()=>{if(!PL.level||PL.level.choices.length<=before)return;const row=document.querySelector('.pl-level-picked>div:last-child');if(!row)return;const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;row.classList.add('pl-picked-new');if(reduce)return;
  const to=row.getBoundingClientRect(),ghost=document.createElement('div');ghost.className='pl-adv-ghost';ghost.textContent='✓ '+label;Object.assign(ghost.style,{left:from.left+'px',top:from.top+'px',width:from.width+'px',height:from.height+'px'});(row.closest('.pl-overlay')||document.body).appendChild(ghost);row.style.opacity='0';
  const anim=ghost.animate([{transform:'none',opacity:1,borderRadius:'12px'},{transform:`translate(${(to.left-from.left)*.5}px,${(to.top-from.top)*.5-30}px) scale(.85)`,opacity:1,offset:.55},{transform:`translate(${to.left-from.left}px,${to.top-from.top}px)`,width:to.width+'px',height:to.height+'px',opacity:.9,borderRadius:'8px'}],{duration:700,easing:'cubic-bezier(.45,.05,.3,1)',fill:'forwards'});
  anim.onfinish=()=>{ghost.remove();row.style.opacity='';row.classList.remove('pl-picked-new');void row.offsetWidth;row.classList.add('pl-picked-new')}}))},true);

// il loadout nella scheda ha sempre i suoi 5 posti (3 sopra, 2 sotto): le carte attive e, al posto di quelle mancanti, uno slot libero
function plLoadoutSlots(c){const cards=c.cards.filter(x=>x.active&&!x.banned).map(x=>plCard(x.i)).filter(Boolean),n=Math.max(5,cards.length);
 const empty=Array.from({length:n-cards.length},(_,k)=>`<div class="pl-slot-empty" aria-label="Slot del loadout libero"><span>＋</span><b>Slot ${cards.length+k+1}</b><small>Sposta qui una carta dal Vault</small></div>`).join('');
 return plCardGrid(cards,[],'manage').replace('class="pl-cards cg"','class="pl-cards cg pl-loadout5"').replace(/<\/div>$/,empty+'</div>')}
